The `getAreasForCommit` function performs sequential git operations inside a loop at line 69-76, which could cause performance issues. For repositories with many commits between releases, this creates an N+1 pattern where N git commands are executed sequentially. Consider batching the git operations or using a single git command to fetch file changes for all commits at once, then parsing the results.
```suggestion
  // Batch-fetch files for all commits in the range to avoid per-commit git calls.
  const logWithFiles = await $`git log v${previous}..HEAD --pretty=format:"%h" --name-only`.text()
  const areaMap = new Map<string, string[]>()
  {
    let currentHash: string | null = null
    for (const rawLine of logWithFiles.split("\n")) {
      const line = rawLine.trim()
      if (!line) continue
      // A line that looks like a short hash marks the start of a commit block.
      if (/^[0-9a-f]{7,40}$/i.test(line)) {
        currentHash = line
        if (!areaMap.has(currentHash)) {
          areaMap.set(currentHash, [])
        }
        continue
      }
      if (!currentHash) continue
      // Determine areas for each file, using the same PACKAGE_PATHS logic as getAreasForCommit.
      for (const pkg of PACKAGE_PATHS) {
        if (line.startsWith(pkg + "/") || line === pkg) {
          const area = pkg.replace("packages/", "").replace("sdks/", "")
          const arr = areaMap.get(currentHash)!
          if (!arr.includes(area)) {
            arr.push(area)
          }
          break
        }
      }
    }
  }

  const commitsWithAreas = commitLines
    .map((line) => {
      const hash = line.split(" ")[0]
      if (!hash) return null
      const areas = areaMap.get(hash) ?? []
      const areaStr = areas.length > 0 ? ` [areas: ${areas.join(", ")}]` : " [areas: other]"
      return `${line}${areaStr}`
    })
    .filter(Boolean) as string[]
```

